/// <summary>
/// NS Zelinka 26.02.24
/// CoC method for init
/// </summary>
/// <returns>boolean - true or false</returns>
public boolean init()
{
    InventJournalTable  inventJournalTable;
    WMSJournalTable     wmsJournalTable;

    boolean ret = next init();

    if (journalTableId == tableNum(InventJournalTable))
    {
        inventJournalTable = InventJournalTable::find(journalId);

        if (inventJournalTable.Posted &&
            (   inventJournalTable.JournalType == InventJournalType::Movement         ||
                inventJournalTable.JournalType == InventJournalType::LossProfit       ||
                inventJournalTable.JournalType == InventJournalType::Transfer         ||
                inventJournalTable.JournalType == InventJournalType::BOM              ||
                inventJournalTable.JournalType == InventJournalType::OwnershipChange  ||
                inventJournalTable.JournalType == InventJournalType::Count            ||
                inventJournalTable.JournalType == InventJournalType::TagCounting)       )
        {
            throw Error("@NDX:NXAPostedRecordCanNotDeleted");
        }
    }

    if (journalTableId == tableNum(WMSJournalTable))
    {
        wmsJournalTable = WMSJournalTable::find(journalId);

        if (wmsJournalTable.Posted &&
            (   wmsJournalTable.JournalType == WMSJournalType::Reception    ||
                wmsJournalTable.JournalType == WMSJournalType::Production)      )
        {
            throw Error("@NDX:NXAPostedRecordCanNotDeleted");
        }
    }

    return ret;
}
